draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var k = p.k, x = p.stretch;
var F = k*x, U = 0.5*k*x*x;

// --- spring picture (top third) ---
var midY = H*0.20, wallX = W*0.08;
var natural = W*0.28;
var pixPerM = W*0.36;
var endX = wallX + natural + x*pixPerM;

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 7, midY - 26, 7, 52);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var i;
for (i = 1; i <= 14; i++) {
  var sx = wallX + (endX - 14 - wallX)*i/14;
  var sy = midY + (i % 2 === 0 ? -9 : 9)*(i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(endX - 14, midY);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(wallX + natural, midY - 30); ctx.lineTo(wallX + natural, midY + 30); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("natural length", wallX + natural - 40, midY - 34);

ctx.fillStyle = C.figure;
ctx.fillRect(endX - 14, midY - 14, 28, 28);
ctx.fillStyle = C.ink;
ctx.fillText("stretch x = " + x.toFixed(2) + " m", endX + 22, midY + 4);

// --- F against x graph (bottom) ---
var L = W*0.12, R = W*0.06, Tp = H*0.42, B = H*0.88;
var xmaxG = 0.60, FmaxG = 260;
function GX(q) { return L + q/xmaxG*(W - L - R); }
function GY(q) { return B - q/FmaxG*(B - Tp); }

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(W - R, B); ctx.stroke();
ctx.beginPath(); ctx.moveTo(L, B); ctx.lineTo(L, Tp); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x (m)", W - R - 34, B + 15);
ctx.fillText("F = kx  (N)", L + 6, Tp + 2);

// shaded triangle = stored energy
var xg = Math.min(x, xmaxG);
var Fg = Math.min(k*xg, FmaxG);
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.25;
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xg), GY(0));
ctx.lineTo(GX(xg), GY(Fg));
ctx.closePath();
ctx.fill();
ctx.globalAlpha = 1;

// the line F = kx
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
var xEnd = Math.min(xmaxG, FmaxG/k);
ctx.beginPath();
ctx.moveTo(GX(0), GY(0));
ctx.lineTo(GX(xEnd), GY(k*xEnd));
ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(GX(xg), GY(0)); ctx.lineTo(GX(xg), GY(Fg)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("area = stored energy = one half k x squared", GX(0) + 12, GY(0) - (B - Tp)*0.12);
ctx.fillText("F = " + F.toFixed(0) + " N", GX(xg) + 6, GY(Fg) - 6);

out.note = "k = " + k.toFixed(0) + " N/m, x = " + x.toFixed(2) + " m: force " + F.toFixed(1) + " N, stored energy " + U.toFixed(2) + " J";
